import{_ as a,o,c as t,ag as r}from"./chunks/framework.D64lb950.js";const u=JSON.parse('{"title":"技术笔记","description":"","frontmatter":{"title":"技术笔记"},"headers":[],"relativePath":"categories/tech-notes.md","filePath":"categories/tech-notes.md","lastUpdated":1781365848000}'),s={name:"categories/tech-notes.md"};function i(d,e,l,c,p,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="📝-技术笔记" tabindex="-1">📝 技术笔记 <a class="header-anchor" href="#📝-技术笔记" aria-label="Permalink to &quot;📝 技术笔记&quot;">​</a></h1><p>记录前端、后端、DevOps 等技术学习心得，分享深度技术文章。</p><h2 id="前端开发" tabindex="-1">前端开发 <a class="header-anchor" href="#前端开发" aria-label="Permalink to &quot;前端开发&quot;">​</a></h2><h3 id="react-hooks-入门指南" tabindex="-1"><a href="/my-blog/posts/react-hooks-guide">React Hooks 入门指南</a> <a class="header-anchor" href="#react-hooks-入门指南" aria-label="Permalink to &quot;[React Hooks 入门指南](/posts/react-hooks-guide)&quot;">​</a></h3><p>React 16.8 引入了 Hooks，让函数组件拥有了类组件的能力。详解 useState、useEffect、useContext、useRef、useMemo、useCallback 等常用 Hooks，演示自定义 Hook 的封装方法。</p><h3 id="vue-3-组合式-api-入门" tabindex="-1"><a href="/my-blog/posts/vue3-composition-api">Vue 3 组合式 API 入门</a> <a class="header-anchor" href="#vue-3-组合式-api-入门" aria-label="Permalink to &quot;[Vue 3 组合式 API 入门](/posts/vue3-composition-api)&quot;">​</a></h3><p>Vue 3 组合式 API 提供了更灵活的组件逻辑组织方式。详解 ref/reactive 响应式绑定、computed/watch 使用，演示组合式函数封装和 TypeScript 支持。</p><h3 id="typescript-类型体操入门" tabindex="-1"><a href="/my-blog/posts/typescript-type-gymnastics">TypeScript 类型体操入门</a> <a class="header-anchor" href="#typescript-类型体操入门" aria-label="Permalink to &quot;[TypeScript 类型体操入门](/posts/typescript-type-gymnastics)&quot;">​</a></h3><p>TypeScript 的类型系统非常强大。从 Partial、Pick、Omit 等基础工具类型，到条件类型、模板字面量、递归类型等进阶技巧，实战实现 ReturnType 和 Parameters。</p><h3 id="css-grid-布局完全指南" tabindex="-1"><a href="/my-blog/posts/css-grid-guide">CSS Grid 布局完全指南</a> <a class="header-anchor" href="#css-grid-布局完全指南" aria-label="Permalink to &quot;[CSS Grid 布局完全指南](/posts/css-grid-guide)&quot;">​</a></h3><p>CSS Grid 是现代网页布局的强大工具。全面介绍网格定义、区域命名、项目定位、对齐方式，提供响应式卡片布局和圣杯布局两个实战案例。</p><h3 id="前端性能优化实战" tabindex="-1"><a href="/my-blog/posts/frontend-performance">前端性能优化实战</a> <a class="header-anchor" href="#前端性能优化实战" aria-label="Permalink to &quot;[前端性能优化实战](/posts/frontend-performance)&quot;">​</a></h3><p>从加载性能、渲染性能、缓存策略三个维度介绍优化策略，详解 Core Web Vitals 监控指标和性能 API 使用方法。</p><h3 id="前端安全防护指南" tabindex="-1"><a href="/my-blog/posts/frontend-security-guide">前端安全防护指南</a> <a class="header-anchor" href="#前端安全防护指南" aria-label="Permalink to &quot;[前端安全防护指南](/posts/frontend-security-guide)&quot;">​</a></h3><p>详解 XSS、CSRF、点击劫持等常见威胁的原理和防护措施，提供 CSP、HttpOnly Cookie、SRI 等安全配置示例。</p><h3 id="vitepress-首页时间戳显示方案对比" tabindex="-1"><a href="/my-blog/posts/vitepress-timestamp-approaches">VitePress 首页时间戳显示方案对比</a> <a class="header-anchor" href="#vitepress-首页时间戳显示方案对比" aria-label="Permalink to &quot;[VitePress 首页时间戳显示方案对比](/posts/vitepress-timestamp-approaches)&quot;">​</a></h3><p>对比四种在 VitePress 首页显示「最近更新时间」的实现方案：Git lastUpdated、Vite define 注入、构建脚本生成、new Date() 直出，分析各自优劣和适用场景。</p><h2 id="后端开发" tabindex="-1">后端开发 <a class="header-anchor" href="#后端开发" aria-label="Permalink to &quot;后端开发&quot;">​</a></h2><h3 id="node-js-异步编程详解" tabindex="-1"><a href="/my-blog/posts/nodejs-async-programming">Node.js 异步编程详解</a> <a class="header-anchor" href="#node-js-异步编程详解" aria-label="Permalink to &quot;[Node.js 异步编程详解](/posts/nodejs-async-programming)&quot;">​</a></h3><p>梳理异步编程从回调到 Promise 再到 async/await 的演进，详解并行执行策略，深入分析 Node.js 事件循环机制。</p><h3 id="restful-api-设计最佳实践" tabindex="-1"><a href="/my-blog/posts/restful-api-design">RESTful API 设计最佳实践</a> <a class="header-anchor" href="#restful-api-设计最佳实践" aria-label="Permalink to &quot;[RESTful API 设计最佳实践](/posts/restful-api-design)&quot;">​</a></h3><p>从 REST 基本原则出发，详解 URL 设计规范、HTTP 方法使用、状态码选择、统一响应格式，以及查询参数的最佳实践。</p><h2 id="devops" tabindex="-1">DevOps <a class="header-anchor" href="#devops" aria-label="Permalink to &quot;DevOps&quot;">​</a></h2><h3 id="docker-容器化部署实践" tabindex="-1"><a href="/my-blog/posts/docker-deployment-guide">Docker 容器化部署实践</a> <a class="header-anchor" href="#docker-容器化部署实践" aria-label="Permalink to &quot;[Docker 容器化部署实践](/posts/docker-deployment-guide)&quot;">​</a></h3><p>从基础概念入手，详解 Dockerfile 编写技巧（包括多阶段构建），介绍 Docker Compose 多容器编排和生产环境最佳实践。</p><h3 id="git-工作流最佳实践" tabindex="-1"><a href="/my-blog/posts/git-workflow">Git 工作流最佳实践</a> <a class="header-anchor" href="#git-工作流最佳实践" aria-label="Permalink to &quot;[Git 工作流最佳实践](/posts/git-workflow)&quot;">​</a></h3><p>介绍分支命名规范、Git Flow 和 GitHub Flow 工作流模式、Conventional Commits 提交规范，详解交互式变基、Cherry-pick、Stash 等高级命令。</p><h2 id="ai-工具" tabindex="-1">AI 工具 <a class="header-anchor" href="#ai-工具" aria-label="Permalink to &quot;AI 工具&quot;">​</a></h2><h3 id="claude-code-入门指南" tabindex="-1"><a href="/my-blog/posts/claude-code-intro">Claude Code 入门指南</a> <a class="header-anchor" href="#claude-code-入门指南" aria-label="Permalink to &quot;[Claude Code 入门指南](/posts/claude-code-intro)&quot;">​</a></h3><p>Claude Code 是 Anthropic 推出的 AI 编程助手命令行工具。介绍安装配置、基本使用命令、实用技巧和 VS Code 集成方法。</p><h3 id="claude-code-高级技巧" tabindex="-1"><a href="/my-blog/posts/claude-code-advanced">Claude Code 高级技巧</a> <a class="header-anchor" href="#claude-code-高级技巧" aria-label="Permalink to &quot;[Claude Code 高级技巧](/posts/claude-code-advanced)&quot;">​</a></h3><p>深入掌握自定义规则、Hooks 系统、多模型协作策略、上下文管理、工作流自动化等高级功能。</p><h3 id="claude-code-实战-构建博客系统" tabindex="-1"><a href="/my-blog/posts/claude-code-practice">Claude Code 实战：构建博客系统</a> <a class="header-anchor" href="#claude-code-实战-构建博客系统" aria-label="Permalink to &quot;[Claude Code 实战：构建博客系统](/posts/claude-code-practice)&quot;">​</a></h3><p>记录使用 Claude Code 从零构建博客系统的完整过程，包括项目规划、功能开发、问题调试和优化改进，AI 辅助比例约 70%。</p><hr><blockquote><p>技术是解决问题的工具，持续学习才能跟上快速变化的开发世界。</p></blockquote>',36)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
